UPDATE knowledge_entry SET title='统计日期与执行范围（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e03ed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='顶部指标筛选与去重（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e04ed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='规划和覆盖支行业务口径（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e05ed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='技能数量与最广使用技能（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e06ed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='任务与客户方案计量口径（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e07ed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='推荐客户与人均口径（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e08ed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='方案查看率业务口径（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e09ed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='接触率业务口径（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e0aed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='机构基准与差值业务口径（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e0bed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='数值单位与空值约定（拆分前历史）', knowledge_type='TECHNICAL', kind='MIXED_LEGACY', status='EXPIRED' WHERE id='328937da8e0ced87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='页面业务说明与接口口径差异', knowledge_type='BUSINESS' WHERE id='328937da8e0fed87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_entry SET title='summary长文本契约（已迁移结构化表）', knowledge_type='TECHNICAL', kind='API_CONTRACT_LEGACY', status='EXPIRED' WHERE id='328937da8e0ded87' AND system_code='LQ13.03' AND project_code='zhituo';
UPDATE knowledge_interface_field SET business_meaning='处理结果业务码',technical_description='业务码，成功为200。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='code';
UPDATE knowledge_interface_field SET business_meaning='处理结果说明',technical_description='结果说明。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='message';
UPDATE knowledge_interface_field SET business_meaning='是否处理成功',technical_description='成功为true。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='success';
UPDATE knowledge_interface_field SET business_meaning='当前筛选范围的顶部统计结果',technical_description='成功时为下列业务对象，失败时为null。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data';
UPDATE knowledge_interface_field SET business_meaning='规划数量',technical_description='规划数，按规划编号去重。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.planCount';
UPDATE knowledge_interface_field SET business_meaning='涉及技能数量',technical_description='技能数，按技能编号去重。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.skillCount';
UPDATE knowledge_interface_field SET business_meaning='成功推荐客户方案数量',technical_description='任务数；成功推荐客户方案数，仅统计plan类型成功最新结果，排除空客户标识，按(trace_id,custuid)去重。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.taskCount';
UPDATE knowledge_interface_field SET business_meaning='应执行任务数量',technical_description='应执行任务数；按目标客户经理工号、规划编号、技能编号、排程日期、任务编号去重，包含未执行任务；无数据为0。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.scheduledTaskCount';
UPDATE knowledge_interface_field SET business_meaning='已执行任务数量，包含失败任务',technical_description='已执行任务数；应执行任务中存在执行记录，失败也算已执行；无数据为0。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.executedTaskCount';
UPDATE knowledge_interface_field SET business_meaning='待执行任务数量',technical_description='待执行任务数；应执行任务中无执行记录，不区分未来和已到期；无数据为0。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.pendingTaskCount';
UPDATE knowledge_interface_field SET business_meaning='已执行任务中的失败任务数量',technical_description='失败任务数；已执行任务最新记录的status不为success；无数据为0。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.failedTaskCount';
UPDATE knowledge_interface_field SET business_meaning='去重推荐客户数量',technical_description='推荐客户数，非空custuid在当前范围整体去重。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.recommendedCustomerCount';
UPDATE knowledge_interface_field SET business_meaning='覆盖支行数量',technical_description='覆盖支行数，按(分行编号,支行编号)去重。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.coveredSubBranchCount';
UPDATE knowledge_interface_field SET business_meaning='使用人数最多的技能',technical_description='使用人数最多的技能；并列按技能编号升序取第一项，无数据为null。父对象非null时该字段适用。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.mostUsedSkill';
UPDATE knowledge_interface_field SET business_meaning='技能编号',technical_description='编号，按编号识别对象。父对象非null时该字段适用。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.mostUsedSkill.id';
UPDATE knowledge_interface_field SET business_meaning='技能名称',technical_description='展示名称。父对象非null时该字段适用。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.mostUsedSkill.name';
UPDATE knowledge_interface_field SET business_meaning='使用该技能的客户经理人数',technical_description='该技能使用人数，按工号去重。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.mostUsedSkill.userCount';
UPDATE knowledge_interface_field SET business_meaning='人均成功推荐客户方案数量',technical_description='人均任务数，四舍五入为整数，无人员为null。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.averageTaskCount';
UPDATE knowledge_interface_field SET business_meaning='人均推荐客户数量',technical_description='人均推荐客户数，四舍五入为整数，无人员为null。父对象非null时该字段适用。64位整数。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.averageRecommendedCustomerCount';
UPDATE knowledge_interface_field SET business_meaning='方案被查看客户占推荐客户的比例',technical_description='方案被查看率，百分比数值。父对象非null时该字段适用。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.viewRate';
UPDATE knowledge_interface_field SET business_meaning='接触客户占推荐客户的比例',technical_description='接触率，百分比数值，可能超过100。父对象非null时该字段适用。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.contactRate';
UPDATE knowledge_interface_field SET business_meaning='机构方案查看基准率',technical_description='机构方案查看基准率。父对象非null时该字段适用。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.benchmarkViewRate';
UPDATE knowledge_interface_field SET business_meaning='机构接触基准率',technical_description='机构接触基准率。父对象非null时该字段适用。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.benchmarkContactRate';
UPDATE knowledge_interface_field SET business_meaning='当前查看率与机构基准的差值',technical_description='查看率减机构基准率，单位百分点。父对象非null时该字段适用。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.viewRateDifference';
UPDATE knowledge_interface_field SET business_meaning='当前接触率与机构基准的差值',technical_description='接触率减机构基准率，单位百分点。父对象非null时该字段适用。' WHERE interface_id=@api_id AND direction='RESPONSE' AND field_path='data.contactRateDifference';
DELETE a FROM knowledge_applicability a JOIN knowledge_entry e ON e.id=a.knowledge_id WHERE e.system_code='LQ13.03' AND e.project_code='zhituo' AND e.kind IN ('API_CONTRACT_LEGACY','MIXED_LEGACY');
DELETE FROM knowledge_entry WHERE system_code='LQ13.03' AND project_code='zhituo' AND kind IN ('API_CONTRACT_LEGACY','MIXED_LEGACY');
COMMIT;
