INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e00584ed87', 'LQ13.03', 'zhituo', '统计日期与执行范围', 'BUSINESS', 'BUSINESS_RULE', '所选排程日期含首尾。排程表示计划安排，不等于已经执行；常规指标只统计已执行范围，任务执行补充指标包含未执行任务。', 'docs/knowledge/shared/report-rules.md RULE_DATE、RULE_TASK；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e03ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
