INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e00587ed87', 'LQ13.03', 'zhituo', '执行记录选择', 'TECHNICAL', 'BUSINESS_RULE', '实际执行日期匹配execute_day且不早于规划创建时间。每任务每天取最新执行记录；时间并列按执行主键倒序。', 'docs/knowledge/shared/report-rules.md RULE_DATE、RULE_TASK；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e03ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
