INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e0058aed87', 'LQ13.03', 'zhituo', '顶部指标筛选与去重', 'BUSINESS', 'BUSINESS_RULE', '机构按目标客户经理归属；分行、支行、等级单选，技能多选取或。各范围独立去重，不能累加每日或子维度数值替代整体。', 'docs/knowledge/shared/report-rules.md RULE_SCOPE；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e04ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
