INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e00590ed87', 'LQ13.03', 'zhituo', '规划和覆盖支行业务口径', 'BUSINESS', 'METRIC_RULE', '规划数为当前执行范围的规划去重数，覆盖支行按分行和支行组合去重。当前接口不额外按生效状态或有效期筛选，不套用规划覆盖模块的三类来源限制。', 'docs/report-api.md 顶部统计及通用约定；docs/knowledge/modules/reports.md；docs/knowledge/shared/report-rules.md RULE_DATE；拆分来源知识ID=328937da8e05ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
