INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e00593ed87', 'LQ13.03', 'zhituo', '规划与机构去重实现', 'TECHNICAL', 'METRIC_RULE', 'planCount按规划编号去重；coveredSubBranchCount按(bbkId,orgId)组合去重；统计归属来自目标客户经理，不使用负责人机构。', 'docs/report-api.md 顶部统计及通用约定；docs/knowledge/modules/reports.md；docs/knowledge/shared/report-rules.md RULE_DATE；拆分来源知识ID=328937da8e05ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
