INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e00596ed87', 'LQ13.03', 'zhituo', '技能数量与最广使用技能', 'BUSINESS', 'METRIC_RULE', '技能数按技能编号去重；使用人数最多技能按客户经理去重人数排名，人数并列按技能编号升序，无数据为空。', 'docs/report-api.md 顶部统计响应字段和统计实现说明；拆分来源知识ID=328937da8e06ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
