INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e00599ed87', 'LQ13.03', 'zhituo', '技能名称冲突处理', 'TECHNICAL', 'METRIC_RULE', '同一技能编号出现多个名称时，当前SQL选取名称最小值，仅影响名称展示，不作为新的业务标识。', 'docs/report-api.md 顶部统计响应字段和统计实现说明；拆分来源知识ID=328937da8e06ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
