INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e0059ced87', 'LQ13.03', 'zhituo', '任务与客户方案计量口径', 'BUSINESS', 'METRIC_RULE', '成功推荐客户方案按客户方案计数，与任务数量单位不同。应执行=已执行+待执行；失败也属于已执行。待执行不区分未来未到期与到期未执行。客户方案数可以大于任务数。', 'docs/knowledge/shared/report-rules.md RULE_TASK、RULE_RESULT；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e07ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_applicability (id, knowledge_id, target_type, target_id, condition_text, unconditional, exception_text, replaces_knowledge_id) VALUES ('328940e0059ded87', '328940e0059ced87', 'COMPONENT', '328937da8dfded87', NULL, 1, NULL, NULL) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_applicability (id, knowledge_id, target_type, target_id, condition_text, unconditional, exception_text, replaces_knowledge_id) VALUES ('328940e0059eed87', '328940e0059ced87', 'INTERFACE', '328937da8e00ed87', NULL, 1, NULL, NULL) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e0059fed87', 'LQ13.03', 'zhituo', '任务及成功方案实现', 'TECHNICAL', 'METRIC_RULE', 'taskCount筛选result_type=plan、最新成功标记=1、结果状态SUC且custuid非空，按(trace_id,custuid)去重。scheduledTaskCount按目标工号、规划、技能、排程日、任务去重；存在执行即executedTaskCount，无执行为pendingTaskCount，最新status非success为failedTaskCount。', 'docs/knowledge/shared/report-rules.md RULE_TASK、RULE_RESULT；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e07ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_applicability (id, knowledge_id, target_type, target_id, condition_text, unconditional, exception_text, replaces_knowledge_id) VALUES ('328940e005a0ed87', '328940e0059fed87', 'COMPONENT', '328937da8dfded87', NULL, 1, NULL, NULL) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_applicability (id, knowledge_id, target_type, target_id, condition_text, unconditional, exception_text, replaces_knowledge_id) VALUES ('328940e005a1ed87', '328940e0059fed87', 'INTERFACE', '328937da8e00ed87', NULL, 1, NULL, NULL) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005a2ed87', 'LQ13.03', 'zhituo', '推荐客户与人均口径', 'BUSINESS', 'METRIC_RULE', '推荐客户按当前范围整体去重，跨技能同一客户只计一次；人均客户方案数和人均推荐客户数分别除以执行客户经理人数，无人员时为空。', 'docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e08ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_applicability (id, knowledge_id, target_type, target_id, condition_text, unconditional, exception_text, replaces_knowledge_id) VALUES ('328940e005a3ed87', '328940e005a2ed87', 'COMPONENT', '328937da8dfded87', NULL, 1, NULL, NULL) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_applicability (id, knowledge_id, target_type, target_id, condition_text, unconditional, exception_text, replaces_knowledge_id) VALUES ('328940e005a4ed87', '328940e005a2ed87', 'INTERFACE', '328937da8e00ed87', NULL, 1, NULL, NULL) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005a5ed87', 'LQ13.03', 'zhituo', '推荐客户与人均实现', 'TECHNICAL', 'METRIC_RULE', 'recommendedCustomerCount按成功推荐结果中非空custuid去重；averageTaskCount=taskCount/userCount，averageRecommendedCustomerCount=recommendedCustomerCount/userCount。Java以BigDecimal及HALF_UP取整数。', 'docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e08ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
