INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005a8ed87', 'LQ13.03', 'zhituo', '方案查看率业务口径', 'BUSINESS', 'METRIC_RULE', '查看率为已查看方案客户数除以推荐客户数；客户在当前范围去重，推荐客户为0时比率为空。', 'docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e09ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
