INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005abed87', 'LQ13.03', 'zhituo', '方案查看率计算实现', 'TECHNICAL', 'METRIC_RULE', 'viewRate将is_read=1执行对应的成功推荐客户去重数除以recommendedCustomerCount并乘100。', 'docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e09ed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
