INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005aeed87', 'LQ13.03', 'zhituo', '接触率业务口径', 'BUSINESS', 'METRIC_RULE', '接触率以推荐客户数为分母，当前接口按关联接触明细中的客户去重，未附加接通等有效性条件，允许超过100%。', 'docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e0aed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
