INSERT INTO knowledge_applicability (id, knowledge_id, target_type, target_id, condition_text, unconditional, exception_text, replaces_knowledge_id) VALUES ('328940e005b0ed87', '328940e005aeed87', 'INTERFACE', '328937da8e00ed87', NULL, 1, NULL, NULL) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005b1ed87', 'LQ13.03', 'zhituo', '接触明细关联实现', 'TECHNICAL', 'METRIC_RULE', '接触通过click_event_id关联点击；事件为button_click或preview_view且template_type=sub。trace_id匹配执行，customer_id匹配推荐客户，点击与执行同日；cust_uid忽略NULL保留空字符串，不额外等于推荐客户标识；contactRate=接触客户去重数/推荐客户数×100。', 'docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e0aed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
