INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005b4ed87', 'LQ13.03', 'zhituo', '机构基准与差值业务口径', 'BUSINESS', 'BUSINESS_RULE', '基准保留日期及分行，移除支行、等级、技能；按整体去重数据计算，不平均支行率。差值为当前率减机构基准率，单位百分点。', 'docs/knowledge/shared/report-rules.md RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e0bed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
