INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005b7ed87', 'LQ13.03', 'zhituo', '机构基准差值实现', 'TECHNICAL', 'BUSINESS_RULE', 'benchmarkViewRate、benchmarkContactRate独立聚合计算；viewRateDifference及contactRateDifference使用双方未舍入值相减，任一分母为0则差值为null。', 'docs/knowledge/shared/report-rules.md RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e0bed87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
