INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005baed87', 'LQ13.03', 'zhituo', '数值单位与空值约定', 'BUSINESS', 'TECHNICAL_RULE', '数量无数据为0，分母为0时比率为空。比率返回百分比数值，百分比和百分点差值保留两位，人均值取整数。', 'docs/knowledge/shared/report-rules.md RULE_RATE；docs/report-api.md 通用约定与顶部统计；拆分来源知识ID=328937da8e0ced87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
