INSERT INTO knowledge_entry (id, system_code, project_code, title, knowledge_type, kind, content, source, status) VALUES ('328940e005bded87', 'LQ13.03', 'zhituo', '数值精度实现', 'TECHNICAL', 'TECHNICAL_RULE', 'Java使用BigDecimal与HALF_UP；JSON数值不保证尾随零，差值以未舍入值计算后舍入，不使用已舍入展示值。', 'docs/knowledge/shared/report-rules.md RULE_RATE；docs/report-api.md 通用约定与顶部统计；拆分来源知识ID=328937da8e0ced87', 'CONFIRMED') ON DUPLICATE KEY UPDATE id=id;
